import 'package:flutter/material.dart'; import '../core/theme.dart'; import '../data/sample_anime.dart';
class SchedulePage extends StatefulWidget{const SchedulePage({super.key});@override State<SchedulePage> createState()=>_SchedulePageState();}
class _SchedulePageState extends State<SchedulePage>{int day=DateTime.now().weekday-1;String filter='Upcoming';@override Widget build(BuildContext c)=>SafeArea(child:Column(children:[const Padding(padding:EdgeInsets.all(20),child:Align(alignment:Alignment.centerLeft,child:Text('Release schedule',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)))),SizedBox(height:70,child:ListView(scrollDirection:Axis.horizontal,children:List.generate(7,(i)=>GestureDetector(onTap:()=>setState(()=>day=i),child:Container(width:55,margin:const EdgeInsets.all(5),decoration:BoxDecoration(color:day==i?appPurple.withValues(alpha:.2):appPanel,borderRadius:BorderRadius.circular(14)),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text(['MON','TUE','WED','THU','FRI','SAT','SUN'][i]),Text('${i+1}',style:const TextStyle(fontSize:18))]))))),Padding(padding:const EdgeInsets.all(12),child:SegmentedButton<String>(segments:const[ButtonSegment(value:'Upcoming',label:Text('Upcoming')),ButtonSegment(value:'Aired',label:Text('Aired today')),ButtonSegment(value:'Mine',label:Text('My anime'))],selected:{filter},onSelectionChanged:(s)=>setState(()=>filter=s.first))),Expanded(child:ListView(children:List.generate(4,(i)=>Card(color:appPanel,child:ListTile(leading:Text(['17:00','18:30','20:00','22:15'][i],style:const TextStyle(color:appCyan)),title:Text(sampleAnime[i].title),subtitle:Text('Episode ${i+1}'),trailing:const Icon(Icons.notifications_none))))))]));}
